import * as React from 'react';
import Portfolio from '../../pages/componentProfile/components/Portfoliop';
import { devError } from '../../common/Utils';
import type { ISpaFeatureProps } from '../../shared/spa/types';
import {
  captureScope,
  isAbortError,
} from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/requestScope';
import { useSpaRouteActive } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/spaRouteActive';
import * as globalCommon from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/globalCommon';

/**
 * Portfolio Profile feature — paint from SPA seed immediately (same as PXC /
 * SPFx feel). TaskUsers load in the background and must not block the page
 * with a full-page skeleton (that looked like a reload).
 */
export default function PortfolioProfileFeature(props: ISpaFeatureProps): React.ReactElement {
  const { pageProps, remountKey } = props;
  const [taskUsers, setTaskUsers] = React.useState<any[]>([]);
  const isRouteActive = useSpaRouteActive();
  const stillMineRef = React.useRef<(() => boolean) | null>(null);

  React.useEffect(() => {
    if (!isRouteActive) {
      // Allow a fresh captureScope() when the user returns to this profile.
      stillMineRef.current = null;
      return;
    }
    if (!stillMineRef.current) {
      stillMineRef.current = captureScope();
    }
    const stillMine = () => isRouteActive && !!stillMineRef.current && stillMineRef.current();
    const load = async (): Promise<void> => {
      try {
        // Reuse TaskUsers across profile item switches (Feature stays mounted).
        if (taskUsers.length > 0) {
          return;
        }
        // Was an inline Task User read with exactly these columns. Note this
        // is NOT the same shape Team Portfolio asks for (no AssingedToUser/EMail,
        // no UserGroupId), so it keeps its own cache entry rather than being
        // handed a roster missing fields it selected.
        const users = await globalCommon.cachedListRead({
          siteUrl: pageProps.siteUrl,
          listId: pageProps.TaskUserListID,
          select: [
            'Id', 'Email', 'Suffix', 'Title', 'Item_x0020_Cover',
            'AssingedToUser/Title', 'AssingedToUser/Id', 'AssingedToUser/Name',
            'UserGroup/Id', 'UserGroup/Title', 'ItemType'
          ],
          expand: ['AssingedToUser', 'UserGroup']
        });
        if (!stillMine()) {
          return;
        }
        setTaskUsers(users || []);
      } catch (error) {
        if (isAbortError(error) || !stillMine()) {
          return;
        }
        devError(error, 'Oops! Something went wrong');
      }
    };
    load();
  }, [pageProps.siteUrl, pageProps.TaskUserListID, isRouteActive, taskUsers.length]);

  // Stay mounted while keep-alive hides the route (same as PXC). Painting
  // Portfoliop immediately lets getPortfolioSeed bind the header without a
  // skeleton flash.
  return (
    <Portfolio
      key={remountKey || 'portfolio-profile'}
      SelectedProp={pageProps}
      TaskUser={taskUsers}
    />
  );
}

