import * as React from 'react';
import ProjectManagementMain from '../../pages/projectManagement/components/ProjectManagementMain';
import { devError } from '../../common/Utils';
import type { ISpaFeatureProps } from '../../shared/spa/types';
import {
  captureScope,
  isAbortError,
} from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/requestScope';
import { useSpaRouteActive } from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/spaRouteActive';
import * as globalCommon from '@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/globalCommon';

/**
 * PXC Profile feature — mirrors PortfolioProfileFeature:
 * TaskUsers load once per feature lifetime; ProjectManagementMain receives them
 * so every ProjectId remount does not re-hit SharePoint.
 */
export default function PxcProfileFeature(props: ISpaFeatureProps): React.ReactElement {
  const { pageProps, remountKey } = props;
  const [taskUsers, setTaskUsers] = React.useState<any[]>([]);
  const [, setUsersReady] = React.useState(true);
  const isRouteActive = useSpaRouteActive();
  const stillMineRef = React.useRef<(() => boolean) | null>(null);

  React.useEffect(() => {
    if (!isRouteActive) {
      stillMineRef.current = null;
      return;
    }
    // Portfolio-style: paint profile from seed immediately; TaskUsers must not
    // block the page — a scope abort on Back used to leave usersReady false forever.
    setUsersReady(true);
    if (!stillMineRef.current) {
      stillMineRef.current = captureScope();
    }
    const stillMine = () =>
      isRouteActive && !!stillMineRef.current && stillMineRef.current();

    const load = async (): Promise<void> => {
      try {
        if (taskUsers.length > 0) {
          return;
        }
        const users = await globalCommon.cachedListRead({
          siteUrl: pageProps.siteUrl,
          listId: pageProps.TaskUserListID,
          select: [
            'Id,UserGroupId,Suffix,IsActive,Title,Email,SortOrder,Role,IsShowTeamLeader,Company,Status,Item_x0020_Cover,AssingedToUserId,isDeleted,AssingedToUser/Title,AssingedToUser/Id,AssingedToUser/EMail,ItemType,Approver/Id,Approver/Title,Approver/Name',
          ],
          expand: ['AssingedToUser', 'Approver'],
          orderBy: [
            ['SortOrder', true],
            ['Title', true],
          ],
        });
        if (!stillMine()) {
          return;
        }
        setTaskUsers(users || []);
      } catch (error) {
        if (isAbortError(error) || !stillMine()) {
          return;
        }
        devError(error, 'Oops! Something went wrong loading Task Users for PXC Profile.');
      }
    };
    load();
  }, [pageProps.siteUrl, pageProps.TaskUserListID, isRouteActive, taskUsers.length]);

  if (!pageProps.Context || !pageProps.Context.pageContext || !pageProps.MasterTaskListID) {
    return null;
  }

  // Portfolio-style: stay mounted while keep-alive hides the route.
  // Returning null unmounted ProjectManagementMain on Back → blank on same-item re-click.
  return (
    <div className="pxc-profile-page relative w-full min-w-0 max-w-full overflow-x-hidden">
      <ProjectManagementMain
        key={remountKey || 'pxc-profile'}
        remountKey={remountKey}
        pageContext={pageProps.Context.pageContext}
        Context={pageProps.Context}
        props={pageProps}
        siteUrl={pageProps.siteUrl}
        TaskUser={taskUsers}
      />
    </div>
  );
}

